{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket lacks server-side encryption",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have server-side encryption enabled. Without encryption, sensitive data stored in the bucket could be exposed if accessed by unauthorized parties."
    },
    {
      "check_id": "CKV_AWS_20",
      "title": "S3 bucket allows public access by default",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not explicitly block public access. This could lead to unintended public exposure of sensitive data."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket lacks versioning",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have versioning enabled. Without versioning, it is harder to recover from accidental deletions or overwrites of objects."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"admin_dashboard\" {\n  bucket = \"smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}\"\n\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        sse_algorithm = \"AES256\"\n      }\n    }\n  }\n\n  versioning {\n    enabled = true\n  }\n\n  block_public_access {\n    block_public_acls       = true\n    block_public_policy     = true\n    ignore_public_acls      = true\n    restrict_public_buckets = true\n  }\n}",
  "fix_summary": "Enabled server-side encryption with AES256 to protect data at rest. Added versioning to allow recovery from accidental deletions or overwrites. Configured block_public_access to prevent unintended public exposure of the bucket."
}
